1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"net"
9		"net/url"
10		"regexp"
11		"strings"
12		"time"
13	
14		"github.com/spf13/cobra"
15	
16		"github.com/entireio/cli/internal/coreapi"
17	)
18	
19	// mirrorColumns is the human table/field view of a mirror: the scannable
20	// repo name, the clone URL you'd copy, and whether the upstream is
21	// private. The cluster is omitted — it's already embedded in the clone
22	// URL — and the wire model's internal ids are dropped entirely. The clone
23	// URL is synthesised from the mirror's coords (the form `git clone`
24	// accepts), since the list API doesn't return it.
25	var mirrorColumns = []string{"REPO", "CLONE URL", "PRIVATE"}
26	
27	func mirrorRow(m coreapi.Mirror) []string {
28		repo := m.Owner + "/" + m.Repo
29		cloneURL := fmt.Sprintf("entire://%s/gh/%s/%s", m.ClusterHost, m.Owner, m.Repo)
30		private := "no"
31		if m.IsPrivate.Or(false) {
32			private = "yes"
33		}
34		return []string{repo, cloneURL, private}
35	}
36	
37	// availableMirrorColumns is the view of a repo you *could* mirror: the
38	// scannable repo name, your effective GitHub access, and whether it's
39	// onboardable. STATUS is "available" (run `entire repo mirror create` to
40	// onboard), "mirrored" (already done — `entire repo mirror list` shows the
41	// clone URL), or "owner-only" (a personal repo of another user; only its
42	// owner may mirror it). No clone URL column: an un-onboarded repo doesn't
43	// have one yet.
44	var availableMirrorColumns = []string{"REPO", "ACCESS", "STATUS"}
45	
46	func availableMirrorRow(m coreapi.AvailableMirror) []string {
47		return []string{m.Owner + "/" + m.Repo, string(m.Access), string(m.Status)}
48	}
49	
50	// defaultClusterHost is the cluster the positional-arg mirror commands target
51	// when the caller omits the <cluster-host> argument. The no-arg create wizard
52	// instead enumerates real clusters from the catalog (GET /api/v1/clusters, see
53	// availableRegions in repo_mirror_create_wizard.go); this stays as the
54	// single-region fallback for the explicit `create <github-url>` form.
55	const defaultClusterHost = "aws-us-east-2.entire.io"
56	
57	// clusterArg returns the cluster host from the optional second positional
58	// (after <github-url>), or defaultClusterHost when it was omitted.
59	func clusterArg(args []string) string {
60		return clusterArgAt(args, 1)
61	}
62	
63	// clusterArgAt returns the cluster host from the optional positional at idx,
64	// or defaultClusterHost when it was omitted. Commands with an intervening
65	// positional (e.g. collaborators add <github-url> <handle> [cluster-host])
66	// pass the trailing index.
67	func clusterArgAt(args []string, idx int) string {
68		if len(args) > idx {
69			return args[idx]
70		}
71		return defaultClusterHost
72	}
73	
74	// clusterHostLabelRe matches one DNS label: alphanumeric, internal hyphens
75	// allowed, no leading/trailing hyphen.
76	var clusterHostLabelRe = regexp.MustCompile(`^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?$`)
77	
78	// validateClusterHost rejects a cluster host that is anything other than a
79	// bare DNS name or IP with an optional :port. The host is concatenated as
80	// "https://"+host into the clone URL and the STS audience
81	// (auth.RepoScopedToken), so a value carrying URL metacharacters can redirect
82	// the request — and the repo-scoped basic-auth token it carries — somewhere
83	// other than the intended cluster. Classic case:
84	// `aws-us-east-2.entire.io@evil.com`, which Go's URL parser reads as
85	// host=evil.com with the real cluster demoted to userinfo, leaking the token
86	// to evil.com. We parse the host the same way the rest of the code does and
87	// require it to round-trip to a bare host with no userinfo, path, query, or
88	// fragment, then confirm the hostname is a valid IP or DNS name. This is
89	// cheap client-side defense-in-depth and doesn't depend on the server's STS
90	// invalid_target canonicalization catching the trick.
91	func validateClusterHost(host string) error {
92		if strings.TrimSpace(host) == "" {
93			return errors.New("cluster host is empty")
94		}
95		u, err := url.Parse("https://" + host)
96		if err != nil {
97			return fmt.Errorf("%q is not a valid host", host)
98		}
99		if u.User != nil || u.Path != "" || u.RawQuery != "" || u.Fragment != "" || u.Host != host {
100			return fmt.Errorf("%q must be a bare host[:port] (no scheme, userinfo, path, query, or fragment)", host)
101		}
102		hostname := u.Hostname()
103		if net.ParseIP(hostname) != nil {
104			return nil
105		}
106		for _, label := range strings.Split(hostname, ".") {
107			if !clusterHostLabelRe.MatchString(label) {
108				return fmt.Errorf("%q is not a valid DNS name or IP", host)
109			}
110		}
111		return nil
112	}
