114	// newRepoMirrorCmd is the `entire repo mirror` subtree: manage EntireDB
115	// GitHub-mirror placements on a cluster. Mirrors the standalone entiredb
116	// CLI's `entire repo mirror` surface for the server-side half (create /
117	// list / get / remove). The local-clone rewrite (`mirror use`) is not
118	// ported — it's a git-config + git-remote-entire concern outside the
119	// control-plane API.
120	func newRepoMirrorCmd() *cobra.Command {
121		cmd := &cobra.Command{
122			Use:   "mirror",
123			Short: "Manage GitHub-mirror placements on EntireDB clusters",
124		}
125		cmd.AddCommand(newRepoMirrorCreateCmd())
126		cmd.AddCommand(newRepoMirrorListCmd())
127		cmd.AddCommand(newRepoMirrorGetCmd())
128		cmd.AddCommand(newRepoMirrorRemoveCmd())
129		cmd.AddCommand(newRepoMirrorCollaboratorsCmd())
130		return cmd
131	}
132	
133	func newRepoMirrorCreateCmd() *cobra.Command {
134		var (
135			noWait      bool
136			waitTimeout time.Duration
137		)
138		cmd := &cobra.Command{
139			Use:   "create [github-url] [cluster-host]",
140			Short: "Register a GitHub mirror on a cluster",
141			Long: "With no arguments, launches an interactive wizard: pick repos to " +
142				"mirror, pick one or more regions, then creates every (repo, region) " +
143				"mirror in parallel and prints the clone URLs.\n\n" +
144				"With a <github-url>, registers a mirror placement for that repo on " +
145				"the target cluster, then waits for the initial GitHub→EntireDB clone " +
146				"to finish so `git clone` works on return. Pass --no-wait to return " +
147				"as soon as the placement is registered. Idempotent on " +
148				"(upstream, cluster). The cluster-host defaults to " +
149				defaultClusterHost + " when omitted (the interactive wizard, with " +
150				"no args, instead lets you pick clusters).",
151			Example: "  entire repo mirror create\n" +
152				"  entire repo mirror create github.com/octocat/hello-world\n" +
153				"  entire repo mirror create github.com/octocat/hello-world aws-us-east-2.entire.io",
154			Args: cobra.RangeArgs(0, 2),
155			RunE: func(cmd *cobra.Command, args []string) error {
156				if len(args) == 0 {
157					return runMirrorCreateWizard(cmd, noWait, waitTimeout)
158				}
159				owner, repo, err := parseGitHubURL(args[0])
160				if err != nil {
161					cmd.SilenceUsage = true
162					return fmt.Errorf("invalid <github-url>: %w", err)
163				}
164				// The non-interactive one-shot keeps a fixed default cluster
165				// (defaultClusterHost) when [cluster-host] is omitted — catalog-based
166				// cluster guessing is intentionally limited to the interactive
167				// wizard (the no-args path above), so scripts get stable behavior.
168				clusterHost := clusterArg(args)
169				if err := validateClusterHost(clusterHost); err != nil {
170					cmd.SilenceUsage = true
171					return fmt.Errorf("invalid [cluster-host]: %w", err)
172				}
173				return runCoreForCluster(cmd, clusterHost, func(ctx context.Context, c *coreapi.Client) error {
174					errW := cmd.ErrOrStderr()
175					stop := startSpinner(errW, fmt.Sprintf("Cloning %s/%s into %s", owner, repo, clusterHost))
176					// nil onStatus: the one-shot's single spinner shows liveness; the
177					// per-mirror progress lines are the wizard's concern.
178					outcome, err := createAndAwaitMirror(ctx, c, owner, repo, clusterHost, noWait, waitTimeout, nil)
179					// Only a confirmed-ready clone earns the ✓; everything else
180					// (empty, --no-wait, suspended, failed, timeout) erases the line
181					// and lets reportOneShotMirror print the specific outcome.
182					stop(err == nil && outcome.polled && outcome.status == coreapi.MirrorStatusReady)
183					return reportOneShotMirror(cmd.OutOrStdout(), errW, outcome, err)
184				})
185			},
186		}
187		cmd.Flags().BoolVar(&noWait, "no-wait", false, "return once the placement is registered, without waiting for the initial clone")
188		cmd.Flags().DurationVar(&waitTimeout, "wait-timeout", 30*time.Minute, "how long to wait for the initial clone to finish")
189		return cmd
190	}
191	
192	// mirrorCreateOutcome bundles the create response with the clone status
193	// observed while waiting. polled is false for --no-wait and for empty upstreams,
194	// where there is nothing to await; in those cases status is unset.
195	type mirrorCreateOutcome struct {
196		created *coreapi.CreatedMirror
197		status  coreapi.MirrorStatus
198		polled  bool
199	}
200	
201	// createAndAwaitMirror is the single create-then-wait path shared by the
202	// `repo mirror create <github-url>` one-shot and the onboarding wizard, so both
203	// report identical lifecycle states. It registers the GitHub mirror on
204	// clusterHost (idempotent on (upstream, cluster)) and, unless noWait or the
205	// upstream is empty, polls the control plane until the clone reaches a terminal
206	// status. The returned error is the create error (when outcome.created is nil)
207	// or the wait error — a status sentinel (errMirrorCloneFailed /
208	// errMirrorSuspended) or a timeout; callers read outcome.status for the state.
209	func createAndAwaitMirror(ctx context.Context, c *coreapi.Client, owner, repo, clusterHost string, noWait bool, timeout time.Duration, onStatus func(coreapi.MirrorStatus)) (mirrorCreateOutcome, error) {
210		created, err := c.CreateMirror(ctx, &coreapi.CreateMirrorInputBody{
211			Provider:    coreapi.CreateMirrorInputBodyProviderGithub,
212			Owner:       owner,
213			Repo:        repo,
214			ClusterHost: clusterHost,
215		})
216		if err != nil {
217			return mirrorCreateOutcome{}, err
218		}
219		outcome := mirrorCreateOutcome{created: created}
220		if created.Empty {
221			// An empty upstream has nothing to clone, so don't poll for "ready" — it
222			// never would. But an *existing* placement can be suspended even when
223			// empty, and one status read surfaces that (a fresh create can't be
224			// suspended — suspension follows upstream access loss). Mirrors the old
225			// finishMirrorCreate behavior; the read is best-effort, so a transient
226			// GetMirror error just falls through to the benign "nothing to clone".
227			if !created.Created {
228				if m, gerr := c.GetMirror(ctx, coreapi.GetMirrorParams{MirrorId: created.MirrorId}); gerr == nil {
229					if s, ok := m.Status.Get(); ok && s == coreapi.MirrorStatusSuspended {
230						outcome.status = s
231						outcome.polled = true
232						return outcome, errMirrorSuspended
233					}
234				}
235			}
236			return outcome, nil
237		}
238		if noWait {
239			return outcome, nil
240		}
241		status, werr := awaitMirrorReady(ctx, c, created.MirrorId, timeout, onStatus)
242		outcome.status = status
243		outcome.polled = true
244		return outcome, werr
245	}
246	
247	// reportOneShotMirror renders the human output for `repo mirror create
248	// <github-url>` from the shared createAndAwaitMirror result. A nil
249	// outcome.created means CreateMirror itself failed — surface that error (nothing
250	// was printed yet). Otherwise echo the placement, then the lifecycle outcome.
251	func reportOneShotMirror(out, errW io.Writer, outcome mirrorCreateOutcome, err error) error {
252		created := outcome.created
253		if created == nil {
254			return err
255		}
256		if created.Created {
257			fmt.Fprintf(out, "Registered mirror %s\n", created.MirrorId)
258		} else {
259			fmt.Fprintf(out, "Mirror already exists (%s)\n", created.MirrorId)
260		}
261		fmt.Fprintf(out, "  %s\n", created.MirrorUrl)
262	
263		if !outcome.polled {
264			if created.Empty {
265				fmt.Fprintln(out, "Upstream has no commits yet — nothing to clone. The mirror will pick up refs once the upstream is pushed to.")
266			} else {
267				fmt.Fprintf(out, "Initial clone may still be in progress; `git clone %s` will work once it completes.\n", created.MirrorUrl)
268			}
269			return nil
270		}
271	
272		switch outcome.status {
273		case coreapi.MirrorStatusReady:
274			fmt.Fprintf(out, "\nClone it:\n  git clone %s\n", created.MirrorUrl)
275			return nil
276		case coreapi.MirrorStatusSuspended:
277			explainSuspendedMirror(errW, created.MirrorId)
278			return NewSilentError(errMirrorSuspended)
279		case coreapi.MirrorStatusFailed:
280			return fmt.Errorf("initial clone of mirror %s failed", created.MirrorId)
281		case coreapi.MirrorStatusProcessing:
282			// Still processing when the poll returned: the wait timed out (or a
283			// transport error broke the poll). awaitMirrorReady's err carries which.
284			return err
285		default:
286			return err
287		}
288	}
289	
290	func newRepoMirrorListCmd() *cobra.Command {
291		var cluster, provider, owner string
292		var showAvailable bool
293		cmd := &cobra.Command{
294			Use:   "list",
295			Short: "List mirrors you can see (or, with --show-available, repos you could mirror)",
296			Args:  cobra.NoArgs,
297			RunE: func(cmd *cobra.Command, _ []string) error {
298				if showAvailable {
299					return runCoreList(cmd, availableMirrorColumns, availableMirrorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.AvailableMirror, error) {
300						// Computed live from GitHub using your own login, so name the
301						// core being dialled (same rationale as the existing-mirror
302						// banner). --cluster/--provider don't apply here: the
303						// onboardable set is cluster-agnostic and GitHub-only.
304						if !jsonRequested(cmd) {
305							fmt.Fprintf(cmd.ErrOrStderr(), "Listing repos you could mirror, via %s\n", c.CoreOrigin())
306						}
307						var params coreapi.ListAvailableMirrorsParams
308						if owner != "" {
309							params.Owner = coreapi.NewOptString(owner)
310						}
311						out, err := c.ListAvailableMirrors(ctx, params)
312						if err != nil {
313							return nil, err
314						}
315						return out.Available, nil
316					})
317				}
318				return runCoreList(cmd, mirrorColumns, mirrorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.Mirror, error) {
319					// mirror list is identity-scoped: it shows the mirrors visible
320					// from the active login's federation, so naming that login server
321					// makes a surprising empty result legible — e.g. mirrors in a
322					// different deployment than the active context (--cluster is a
323					// filter, not a router). Name the core the client actually dials
324					// (c.CoreOrigin) so the banner can never diverge from where the
325					// request goes — in particular it reflects ENTIRE_TOKEN's aud,
326					// which a separately-resolved ResolveControlPlaneTarget would miss.
327					// On stderr so it never lands in a piped table; skipped for --json
328					// to keep machine output clean.
329					if !jsonRequested(cmd) {
330						fmt.Fprintf(cmd.ErrOrStderr(), "Listing mirrors on %s\n", c.CoreOrigin())
331					}
332					return fetchAllPages(ctx, func(ctx context.Context, cursor string) ([]coreapi.Mirror, string, error) {
333						params := coreapi.ListMirrorsParams{}
334						if cluster != "" {
335							params.Cluster = coreapi.NewOptString(cluster)
336						}
337						if provider != "" {
338							params.Provider = coreapi.NewOptString(provider)
339						}
340						if owner != "" {
341							params.Owner = coreapi.NewOptString(owner)
342						}
343						if cursor != "" {
344							params.PageToken = coreapi.NewOptString(cursor)
345						}
346						out, err := c.ListMirrors(ctx, params)
347						if err != nil {
348							return nil, "", err
349						}
350						return out.Mirrors, out.NextPageToken.Or(""), nil
351					})
352				})
353			},
354		}
355		cmd.Flags().StringVar(&cluster, "cluster", "", "filter by cluster public host")
356		cmd.Flags().StringVar(&provider, "provider", "", "filter by upstream provider (e.g. github)")
357		cmd.Flags().StringVar(&owner, "owner", "", "filter by upstream owner login")
358		cmd.Flags().BoolVar(&showAvailable, "show-available", false, "instead of existing mirrors, list GitHub repos you could onboard as mirrors (ignores --cluster/--provider)")
359		return cmd
360	}
361	
362	func newRepoMirrorGetCmd() *cobra.Command {
363		return &cobra.Command{
364			Use:   "get <mirror-id>",
365			Short: "Show a mirror by ULID",
366			Args:  cobra.ExactArgs(1),
367			RunE: func(cmd *cobra.Command, args []string) error {
368				return runCoreObject(cmd, mirrorColumns, mirrorRow, func(ctx context.Context, c *coreapi.Client) (*coreapi.Mirror, error) {
369					sc, err := c.GetMirror(ctx, coreapi.GetMirrorParams{MirrorId: args[0]})
370					if err != nil {
371						return nil, err
372					}
373					return sc, nil
374				})
375			},
376		}
377	}
378	
379	func newRepoMirrorRemoveCmd() *cobra.Command {
380		return &cobra.Command{
381			Use:   "remove <github-url> [cluster-host]",
382			Short: "Un-register a GitHub mirror from a cluster",
383			Long: "Removes a mirror placement for a GitHub repo from the target " +
384				"cluster. Other clusters' placements of the same upstream are " +
385				"unaffected. The cluster-host defaults to " + defaultClusterHost +
386				" when omitted.",
387			Example: "  entire repo mirror remove github.com/octocat/hello-world",
388			Args:    cobra.RangeArgs(1, 2),
389			RunE: func(cmd *cobra.Command, args []string) error {
390				owner, repo, err := parseGitHubURL(args[0])
391				if err != nil {
392					cmd.SilenceUsage = true
393					return fmt.Errorf("invalid <github-url>: %w", err)
394				}
395				clusterHost := clusterArg(args)
396				if err := validateClusterHost(clusterHost); err != nil {
397					cmd.SilenceUsage = true
398					return fmt.Errorf("invalid [cluster-host]: %w", err)
399				}
400				return runCoreForCluster(cmd, clusterHost, func(ctx context.Context, c *coreapi.Client) error {
401					// Delete by upstream coords in one call. A 404 is a real
402					// error here, not idempotent success: the server only
403					// answers 204 when it actually removed a placement, so a
404					// 404 ("no such mirror / not visible / different cluster")
405					// surfaces verbatim via renderCoreError rather than being
406					// reported as a successful removal.
407					if err := c.DeleteMirror(ctx, coreapi.DeleteMirrorParams{
408						Provider:    coreapi.DeleteMirrorProviderGithub,
409						Owner:       owner,
410						Repo:        repo,
411						ClusterHost: clusterHost,
412					}); err != nil {
413						return err
414					}
415					cmd.Printf("Removed mirror github.com/%s/%s from %s\n", owner, repo, clusterHost)
416					return nil
417				})
418			},
419		}
420	}
