19		"github.com/entireio/cli/cmd/entire/cli/auth"
20		"github.com/entireio/cli/cmd/entire/cli/interactive"
21		"github.com/entireio/cli/internal/coreapi"
22	)
23	
24	// mirrorCreateConcurrency bounds how many (repo, region) mirror creations run
25	// at once. The slow phase is the per-mirror clone wait, which is I/O-bound on
26	// the cluster, so a modest fan-out keeps the wizard responsive without
27	// hammering the control plane or the user's STS.
28	const mirrorCreateConcurrency = 8
29	
30	// Per-mirror outcome labels shown in the results table's STATUS column.
31	const (
32		mirrorStatusReady      = "ready"      // clone landed, ready to use
33		mirrorStatusRegistered = "registered" // placement created, clone in progress (--no-wait)
34		mirrorStatusEmpty      = "empty"      // upstream has no commits, nothing to clone
35		mirrorStatusSuspended  = "suspended"  // placement exists but the cluster won't serve it
36		mirrorStatusFailed     = "failed"     // initial clone reached the terminal failed status
37		mirrorStatusTimedOut   = "timed out"  // clone didn't finish within --wait-timeout
38		mirrorStatusError      = "error"      // create or poll failed
39	)
40	
41	// regionChoice is one mirrorable region offered by the create wizard's region
42	// picker, sourced from the control plane's cluster catalog
43	// (GET /api/v1/clusters via availableRegions).
44	type regionChoice struct {
45		slug         string
46		jurisdiction string
47		host         string // bare cluster host passed to CreateMirror / validateClusterHost
48		isDefault    bool
49	}
50	
51	// availableRegions lists the data-plane clusters the user may mirror into,
52	// fetched from the control plane's cluster catalog. A cluster whose advertised
53	// public URL can't be safely reduced to a bare host (hostFromPublicURL) is
54	// skipped rather than failing the whole wizard, so a single malformed entry
55	// can't block onboarding into the others.
56	func availableRegions(ctx context.Context, c *coreapi.Client) ([]regionChoice, error) {
57		out, err := c.ListClusters(ctx)
58		if err != nil {
59			return nil, renderCoreError(err)
60		}
61		return clustersToRegions(out.Clusters), nil
62	}
63	
64	// clustersToRegions maps the catalog's clusters to picker choices, dropping any
65	// whose advertised public URL can't be safely reduced to a bare host.
66	func clustersToRegions(clusters []coreapi.Cluster) []regionChoice {
67		regions := make([]regionChoice, 0, len(clusters))
68		for _, cl := range clusters {
69			host, herr := hostFromPublicURL(cl.PublicUrl)
70			if herr != nil {
71				continue
72			}
73			regions = append(regions, regionChoice{
74				slug:         cl.Slug,
75				jurisdiction: cl.Jurisdiction,
76				host:         host,
77				isDefault:    cl.IsDefault,
78			})
79		}
80		return regions
81	}
82	
83	// hostFromPublicURL extracts the bare cluster host from a cluster's public_url
84	// (with or without a scheme) and runs it through validateClusterHost, the same
85	// anti-token-leak guard the positional <cluster-host> arg uses. Kept separate
86	// so the ListClusters → regionChoice mapping is unit-testable without a live
87	// catalog.
88	func hostFromPublicURL(raw string) (string, error) {
89		s := strings.TrimSpace(raw)
90		if s == "" {
91			return "", errors.New("empty public_url")
92		}
93		if !strings.Contains(s, "://") {
94			s = "https://" + s
95		}
96		u, err := url.Parse(s)
97		if err != nil {
98			return "", fmt.Errorf("parse public_url %q: %w", raw, err)
99		}
100		if u.Host == "" {
101			return "", fmt.Errorf("public_url %q has no host", raw)
102		}
103		// Reject anything beyond scheme://host[:port]. url.Parse demotes the
104		// `host@evil.com` userinfo trick into u.User (leaving u.Host=evil.com) and
105		// stashes a trailing path in u.Path, neither of which validateClusterHost
106		// would otherwise see. A bare "/" path is tolerated: publicUrl is a trusted
107		// catalog field, and a trailing slash (https://host/) is benign — rejecting
108		// it would silently drop the cluster and could leave the wizard with no
109		// regions. Anything richer (a real path, query, fragment, userinfo) is still
110		// refused, since the host flows into clone URLs and the STS audience.
111		if u.User != nil || (u.Path != "" && u.Path != "/") || u.RawQuery != "" || u.Fragment != "" {
112			return "", fmt.Errorf("public_url %q must be scheme://host[:port] only", raw)
113		}
114		if err := validateClusterHost(u.Host); err != nil {
115			return "", err
116		}
117		return u.Host, nil
118	}
119	
120	// selectableAvailableRepos narrows the ListAvailableMirrors result to repos the
121	// wizard should offer: status "available" (not already mirrored or owner-only)
122	// with write or admin access (read-only can't be onboarded). Sorted by
123	// owner/repo for a stable picker order.
124	func selectableAvailableRepos(avail []coreapi.AvailableMirror) []coreapi.AvailableMirror {
125		out := make([]coreapi.AvailableMirror, 0, len(avail))
126		for _, m := range avail {
127			if m.Status != coreapi.AvailableMirrorStatusAvailable {
128				continue
129			}
130			if m.Access != coreapi.AvailableMirrorAccessWrite && m.Access != coreapi.AvailableMirrorAccessAdmin {
131				continue
132			}
133			out = append(out, m)
134		}
135		sort.Slice(out, func(i, j int) bool {
136			if out[i].Owner != out[j].Owner {
137				return out[i].Owner < out[j].Owner
138			}
139			return out[i].Repo < out[j].Repo
140		})
141		return out
142	}
143	
144	// multiSelectHeight returns an explicit huh multi-select Height that keeps every
145	// option visible. huh auto-sizes an unset height to (rendered option lines −
146	// title/description rows), which collapses to ~1 visible row for short lists
147	// (e.g. 3 regions vs. a long repo list) — the cause of the region picker
148	// appearing clamped to one option. We set it to the option count plus slack for
149	// the title + (possibly wrapped) description so the whole list shows; huh still
150	// scrolls if the list outgrows the terminal.
151	func multiSelectHeight(n int) int {
152		const headerSlack = 3 // title (1) + description (1–2 when wrapped)
153		return n + headerSlack
154	}
155	
156	// clusterChoices maps regions to multi-select options (value = bare host),
157	// listing every cluster, and returns the host(s) that should start checked:
158	// the default cluster for the caller's jurisdiction. is_default is
159	// per-jurisdiction, so pre-selecting only the caller's avoids defaulting a repo
160	// into every jurisdiction. With no jurisdiction nothing is pre-checked (the user
161	// picks). All clusters stay selectable regardless.
162	//
163	// The caller's-jurisdiction clusters are listed first so that on a short
164	// terminal — where huh's option viewport shows only the top rows — the visible,
165	// pre-checked default is the relevant one, not some other jurisdiction's.
166	func clusterChoices(regions []regionChoice, jurisdiction string) (opts []huh.Option[string], defaults []string) {
167		ordered := make([]regionChoice, len(regions))
168		copy(ordered, regions)
169		if jurisdiction != "" {
170			sort.SliceStable(ordered, func(i, j int) bool {
171				return ordered[i].jurisdiction == jurisdiction && ordered[j].jurisdiction != jurisdiction
172			})
173		}
174		opts = make([]huh.Option[string], 0, len(ordered))
175		for _, r := range ordered {
176			opts = append(opts, huh.NewOption(regionLabel(r), r.host))
177			if jurisdiction != "" && r.isDefault && r.jurisdiction == jurisdiction {
178				defaults = append(defaults, r.host)
179			}
180		}
181		return opts, defaults
182	}
183	
184	// regionLabel is the human label for a region in the picker and the results
185	// table: "slug (jurisdiction)" when both are known, else whatever identifier we
186	// have, falling back to the bare host.
187	func regionLabel(r regionChoice) string {
188		switch {
189		case r.slug != "" && r.jurisdiction != "":
190			return fmt.Sprintf("%s (%s)", r.slug, r.jurisdiction)
191		case r.slug != "":
192			return r.slug
193		default:
194			return r.host
195		}
196	}
197	
198	// mirrorTarget is one unit of work: a selected repo to be mirrored into a
199	// selected region. The wizard creates the cross-product of repos × regions.
200	type mirrorTarget struct {
201		owner  string
202		repo   string
203		region regionChoice
204	}
205	
206	// mirrorTargets expands the selected repos and regions into the full
207	// cross-product of (repo, region) pairs.
208	func mirrorTargets(repos []coreapi.AvailableMirror, regions []regionChoice) []mirrorTarget {
209		targets := make([]mirrorTarget, 0, len(repos)*len(regions))
210		for _, r := range repos {
211			for _, reg := range regions {
212				targets = append(targets, mirrorTarget{owner: r.Owner, repo: r.Repo, region: reg})
213			}
214		}
215		return targets
216	}
217	
218	// mirrorResult is the outcome of creating one (repo, region) mirror.
219	type mirrorResult struct {
220		owner       string
221		repo        string
222		regionLabel string
223		cloneURL    string
224		status      string // ready | registered | empty | suspended | timed out | error
225		err         error
226	}
227	
228	var mirrorCreateResultColumns = []string{"REPO", "REGION", "STATUS", "CLONE URL"}
229	
230	func mirrorCreateResultRow(r mirrorResult) []string {
231		url := r.cloneURL
232		if url == "" {
233			url = placeholderDash
234		}
235		return []string{r.owner + "/" + r.repo, r.regionLabel, r.status, url}
236	}
237	
238	// runMirrorCreateWizard is the zero-argument `entire repo mirror create` flow:
239	// verify auth, pick repos, pick regions, then create the cross-product of
240	// mirrors in parallel and report the clone URLs. noWait/waitTimeout carry the
241	// same meaning as the positional-arg create path.
242	func runMirrorCreateWizard(cmd *cobra.Command, noWait bool, waitTimeout time.Duration) error {
243		cmd.SilenceUsage = true
244		ctx := cmd.Context()
245		outW := cmd.OutOrStdout()
246		errW := cmd.ErrOrStderr()
247	
248		// The wizard drives interactive huh pickers, so it needs a real terminal.
249		// Without one (CI, pipes), fail fast with a clear pointer at the
250		// non-interactive form rather than letting huh error obscurely.
251		if !interactive.CanPromptInteractively() {
252			fmt.Fprintln(errW, "The mirror create wizard needs an interactive terminal.")
253			fmt.Fprintln(errW, "Run 'entire repo mirror create <github-url> [cluster-host]' to create one non-interactively.")
254			return NewSilentError(errors.New("not an interactive terminal"))
255		}
256	
257		insecure := insecureHTTPRequested(cmd)
258		if insecure {
259			auth.EnableInsecureHTTP()
260		}
261	
262		jurisdiction, err := ensureMirrorWizardAuth(ctx, errW, insecure)
263		if err != nil {
264			return err
265		}
266	
267		client, err := coreapi.New()
268		if err != nil {
269			return fmt.Errorf("connect to Entire control plane: %w", err)
270		}
271	
272		// --- pick repos ---------------------------------------------------------
273		stopRepos := startSpinner(errW, "Fetching available repos")
274		avail, err := client.ListAvailableMirrors(ctx, coreapi.ListAvailableMirrorsParams{})
275		if err != nil {
276			stopRepos(false)
277			return renderCoreError(err)
278		}
279		stopRepos(true)
280		repos := selectableAvailableRepos(avail.Available)
281		if len(repos) == 0 {
282			fmt.Fprintln(errW, "No GitHub repos available to mirror (you need write access to a repo that isn't mirrored yet).")
283			fmt.Fprintln(errW, "Run 'entire repo mirror list --show-available' to see what's onboardable.")
284			return nil
285		}
286		selectedRepos, err := pickRepos(ctx, outW, repos)
287		if err != nil || len(selectedRepos) == 0 {
288			return err
289		}
290	
291		// --- pick regions -------------------------------------------------------
292		stopRegions := startSpinner(errW, "Fetching regions")
293		regions, err := availableRegions(ctx, client)
294		if err != nil {
295			stopRegions(false)
296			return fmt.Errorf("list regions: %w", err)
297		}
298		stopRegions(true)
299		if len(regions) == 0 {
300			return errors.New("no regions available to mirror into")
301		}
302		selectedRegions, err := pickRegions(ctx, outW, regions, jurisdiction)
303		if err != nil || len(selectedRegions) == 0 {
304			return err
305		}
306	
307		// --- create + poll ------------------------------------------------------
308		targets := mirrorTargets(selectedRepos, selectedRegions)
309		results := createMirrors(ctx, errW, targets, noWait, waitTimeout)
310	
311		// A cancelled run (Ctrl+C) leaves in-flight mirrors looking like errors;
312		// exit quietly instead of reporting them as "N mirror(s) failed".
313		if ctx.Err() != nil {
314			return NewSilentError(ctx.Err())
315		}
316		return reportMirrorResults(outW, errW, results)
317	}
318	
319	// ensureMirrorWizardAuth mirrors `entire auth status`: resolve the active
320	// target (honouring ENTIRE_TOKEN), enforce TLS on the core we'll dial, and
321	// validate the token with a /me probe so the wizard fails fast with a re-login
322	// hint rather than deep inside the first API call. Returns the caller's home
323	// jurisdiction (from /me, may be "") so the region picker can pre-select that
324	// jurisdiction's default cluster.
325	func ensureMirrorWizardAuth(ctx context.Context, errW io.Writer, insecure bool) (string, error) {
326		target, err := resolveAuthStatusTarget(ctx, auth.Contexts, auth.RefreshedLoginToken)
327		if err != nil {
328			return "", err
329		}
330		if target.token == "" {
331			fmt.Fprintln(errW, "Not logged in. Run 'entire login' to authenticate.")
332			return "", NewSilentError(errors.New("not logged in"))
333		}
334		if !insecure && target.coreURL != "" {
335			if err := api.RequireSecureURL(target.coreURL); err != nil {
336				return "", fmt.Errorf("login server URL check: %w", err)
337			}
338		}
339		profile, err := defaultFetchProfile(ctx, target.coreURL, target.token)
340		if err != nil {
341			if isKeychainTokenRejected(err) {
342				fmt.Fprintf(errW, "Login for %s is no longer valid. Run 'entire login' to re-authenticate.\n", target.coreURL)
343				return "", NewSilentError(errors.New("login no longer valid"))
344			}
345			return "", fmt.Errorf("validate auth: %w", err)
346		}
347		if profile.Jurisdiction != "" {
348			fmt.Fprintf(errW, "Signed in as %s (%s) via %s\n", profile.Handle, profile.Jurisdiction, target.coreURL)
349		} else {
350			fmt.Fprintf(errW, "Signed in as %s via %s\n", profile.Handle, target.coreURL)
351		}
352		return profile.Jurisdiction, nil
353	}
354	
355	// pickRepos runs the repo multi-select and returns the chosen available
356	// mirrors. A clean cancel (Ctrl+C / cancelled ctx) returns (nil, nil).
357	func pickRepos(ctx context.Context, w io.Writer, repos []coreapi.AvailableMirror) ([]coreapi.AvailableMirror, error) {
358		repoByKey := make(map[string]coreapi.AvailableMirror, len(repos))
359		options := make([]huh.Option[string], len(repos))
360		for i, m := range repos {
361			key := m.Owner + "/" + m.Repo
362			repoByKey[key] = m
363			options[i] = huh.NewOption(key, key)
364		}
365	
366		var selected []string
367		form := NewAccessibleForm(
368			huh.NewGroup(
369				huh.NewMultiSelect[string]().
370					Title("Select repos to mirror").
371					Description("Space to select, enter to confirm.").
372					Options(options...).
373					Height(multiSelectHeight(len(options))).
374					Validate(func(s []string) error {
375						if len(s) == 0 {
376							return errors.New("select at least one repo")
377						}
378						return nil
379					}).
380					Value(&selected),
381			),
382		)
383		if err := form.RunWithContext(ctx); err != nil {
384			return nil, handleFormCancellation(w, "Mirror create", err)
385		}
386	
387		chosen := make([]coreapi.AvailableMirror, 0, len(selected))
388		for _, key := range selected {
389			if m, ok := repoByKey[key]; ok {
390				chosen = append(chosen, m)
391			}
392		}
393		return chosen, nil
394	}
395	
396	// pickRegions runs the region multi-select, pre-selecting the default cluster
397	// for the caller's jurisdiction. A clean cancel returns (nil, nil).
398	func pickRegions(ctx context.Context, w io.Writer, regions []regionChoice, jurisdiction string) ([]regionChoice, error) {
399		opts, defaults := clusterChoices(regions, jurisdiction)
400		regionByHost := make(map[string]regionChoice, len(regions))
401		for _, r := range regions {
402			regionByHost[r.host] = r
403		}
404	
405		// Pre-fill with the default hosts so they start checked.
406		selected := append([]string(nil), defaults...)
407		form := NewAccessibleForm(
408			huh.NewGroup(
409				huh.NewMultiSelect[string]().
410					Title("Select regions to mirror into").
411					Description("Each repo is mirrored into every selected region.").
412					Options(opts...).
413					Height(multiSelectHeight(len(opts))).
414					Validate(func(s []string) error {
415						if len(s) == 0 {
416							return errors.New("select at least one region")
417						}
418						return nil
419					}).
420					Value(&selected),
421			),
422		)
423		if err := form.RunWithContext(ctx); err != nil {
424			return nil, handleFormCancellation(w, "Mirror create", err)
425		}
426	
427		chosen := make([]regionChoice, 0, len(selected))
428		for _, host := range selected {
429			if r, ok := regionByHost[host]; ok {
430				chosen = append(chosen, r)
431			}
432		}
433		return chosen, nil
434	}
435	
436	// createMirrors fans out CreateMirror (and the clone-readiness poll) across all
437	// targets in parallel, returning one result per target in input order. One
438	// cluster client is built per region and shared across that region's repos; a
439	// region the active login can't reach fails every pair in that region rather
440	// than aborting the whole run.
441	func createMirrors(ctx context.Context, errW io.Writer, targets []mirrorTarget, noWait bool, waitTimeout time.Duration) []mirrorResult {
442		// One client per distinct region, built once.
443		clientByHost := make(map[string]*coreapi.Client)
444		clientErrByHost := make(map[string]error)
445		for _, t := range targets {
446			if _, seen := clientByHost[t.region.host]; seen {
447				continue
448			}
449			if _, seen := clientErrByHost[t.region.host]; seen {
450				continue
451			}
452			c, err := coreapi.NewForCluster(ctx, t.region.host)
453			if err != nil {
454				clientErrByHost[t.region.host] = err
455			} else {
456				clientByHost[t.region.host] = c
457			}
458		}
459	
460		// Docker-pull-style live progress: one line per (repo, region), each
461		// updating independently as its CreateMirror + clone poll advance.
462		labels := make([]string, len(targets))
463		for i, t := range targets {
464			labels[i] = t.owner + "/" + t.repo + " @ " + t.region.host
465		}
466		prog := newMirrorProgress(errW, labels)
467		prog.start()
468	
469		results := make([]mirrorResult, len(targets))
470		g := new(errgroup.Group)
471		g.SetLimit(mirrorCreateConcurrency)
472		for i, t := range targets {
473			g.Go(func() error {
474				results[i] = createOneMirror(ctx, t, clientByHost[t.region.host], clientErrByHost[t.region.host], noWait, waitTimeout,
475					func(status string, final, ok bool) { prog.set(i, status, final, ok) })
476				return nil
477			})
478		}
479		// createOneMirror folds every failure into results and never returns an
480		// error, so Wait is structurally always nil; check it anyway to satisfy
481		// errcheck and stay correct if that invariant ever changes.
482		if err := g.Wait(); err != nil {
483			fmt.Fprintf(errW, "mirror creation: %v\n", err)
484		}
485		prog.stop()
486		return results
487	}
488	
489	// createOneMirror registers a single (repo, region) mirror and, unless noWait
490	// or the upstream is empty, waits for its initial clone. It never returns an
491	// error: every outcome is folded into the mirrorResult so a single failure
492	// can't sink the batch. report (may be nil) is called as the mirror moves
493	// through its phases so the caller can render live progress; the final call has
494	// final=true and ok set to whether it succeeded.
495	func createOneMirror(ctx context.Context, t mirrorTarget, c *coreapi.Client, clientErr error, noWait bool, waitTimeout time.Duration, report func(status string, final, ok bool)) mirrorResult {
496		if report == nil {
497			report = func(string, bool, bool) {}
498		}
499		res := mirrorResult{owner: t.owner, repo: t.repo, regionLabel: regionLabel(t.region)}
500		if clientErr != nil {
501			res.status, res.err = mirrorStatusError, clientErr
502			report(mirrorStatusError, true, false)
503			return res
504		}
505		report("creating", false, false)
506		// Same create-then-wait path as the one-shot `repo mirror create <url>`
507		// (createAndAwaitMirror), so both report identical lifecycle states. The
508		// per-poll status drives this mirror's progress line.
509		outcome, err := createAndAwaitMirror(ctx, c, t.owner, t.repo, t.region.host, noWait, waitTimeout,
510			func(s coreapi.MirrorStatus) { report(string(s), false, false) })
511		if outcome.created == nil {
512			res.status, res.err = mirrorStatusError, renderCoreError(err)
513			report(mirrorStatusError, true, false)
514			return res
515		}
516		res.cloneURL = outcome.created.MirrorUrl
517	
518		if !outcome.polled {
519			if outcome.created.Empty {
520				res.status = mirrorStatusEmpty
521			} else {
522				res.status = mirrorStatusRegistered
523			}
524			report(res.status, true, true)
525			return res
526		}
527	
528		// nonTerminal classifies a still-processing/unknown result: the poll ended
529		// without a terminal status, so the wait timed out or a poll call errored.
530		nonTerminal := func() {
531			if errors.Is(err, context.DeadlineExceeded) {
532				res.status, res.err = mirrorStatusTimedOut, err
533			} else {
534				res.status, res.err = mirrorStatusError, err
535			}
536		}
537		switch outcome.status {
538		case coreapi.MirrorStatusReady:
539			res.status = mirrorStatusReady
540		case coreapi.MirrorStatusSuspended:
541			res.status, res.err = mirrorStatusSuspended, errors.New("the mirror is suspended; contact support")
542		case coreapi.MirrorStatusFailed:
543			res.status, res.err = mirrorStatusFailed, errors.New("the initial clone failed; contact support")
544		case coreapi.MirrorStatusProcessing:
545			nonTerminal()
546		default:
547			nonTerminal()
548		}
549		report(res.status, true, res.err == nil)
550		return res
551	}
552	
553	// mirrorProgress renders a Docker-pull-style live list: one line per mirror,
554	// each showing its label and a status that updates independently — a spinner
555	// while in flight, ✓/✗ once terminal. On a non-terminal writer (pipes, tests)
556	// it degrades to one printed line per mirror as each reaches a terminal state.
557	type mirrorProgress struct {
558		w       io.Writer
559		tty     bool
560		labelW  int
561		mu      sync.Mutex
562		lines   []mirrorProgressLine
563		frame   int
564		painted bool
565		done    chan struct{}
566		stopped chan struct{}
567	}
568	
569	type mirrorProgressLine struct {
570		label   string
571		status  string
572		final   bool
573		ok      bool
574		printed bool // non-tty: terminal line already emitted
575	}
576	
577	func newMirrorProgress(w io.Writer, labels []string) *mirrorProgress {
578		lines := make([]mirrorProgressLine, len(labels))
579		labelW := 0
580		for i, l := range labels {
581			lines[i] = mirrorProgressLine{label: l, status: "queued"}
582			if n := len(l); n > labelW {
583				labelW = n
584			}
585		}
586		return &mirrorProgress{w: w, tty: interactive.IsTerminalWriter(w), labelW: labelW, lines: lines}
587	}
588	
589	// start paints the initial block and, on a TTY, begins animating the spinner.
590	func (p *mirrorProgress) start() {
591		if !p.tty {
592			return
593		}
594		p.done = make(chan struct{})
595		p.stopped = make(chan struct{})
596		p.mu.Lock()
597		p.renderLocked()
598		p.mu.Unlock()
599		go func() {
600			defer close(p.stopped)
601			ticker := time.NewTicker(spinnerInterval)
602			defer ticker.Stop()
603			for {
604				select {
605				case <-p.done:
606					return
607				case <-ticker.C:
608					p.mu.Lock()
609					p.frame++
610					p.renderLocked()
611					p.mu.Unlock()
612				}
613			}
614		}()
615	}
616	
617	// set updates one mirror's line. On a TTY it repaints immediately; otherwise it
618	// prints a single line the first time the mirror reaches a terminal state.
619	func (p *mirrorProgress) set(i int, status string, final, ok bool) {
620		p.mu.Lock()
621		defer p.mu.Unlock()
622		p.lines[i].status = status
623		p.lines[i].final = final
624		p.lines[i].ok = ok
625		switch {
626		case p.tty:
627			p.renderLocked()
628		case final && !p.lines[i].printed:
629			p.lines[i].printed = true
630			fmt.Fprintf(p.w, "%s %s %s\n", terminalIcon(ok), p.lines[i].label, status)
631		}
632	}
633	
634	// stop ends the animation and leaves the final state painted.
635	func (p *mirrorProgress) stop() {
636		if !p.tty {
637			return
638		}
639		close(p.done)
640		<-p.stopped
641		p.mu.Lock()
642		p.renderLocked()
643		p.mu.Unlock()
644	}
645	
646	// renderLocked repaints the whole block in place. Caller holds p.mu.
647	func (p *mirrorProgress) renderLocked() {
648		if p.painted {
649			fmt.Fprintf(p.w, "\033[%dA", len(p.lines)) // move up to the block's top
650		}
651		p.painted = true
652		for _, ln := range p.lines {
653			var icon string
654			if ln.final {
655				icon = terminalIcon(ln.ok)
656			} else {
657				icon = spinnerFrames[p.frame%len(spinnerFrames)]
658			}
659			fmt.Fprintf(p.w, "\r\033[K%-*s  %s %s\n", p.labelW, ln.label, icon, ln.status)
660		}
661	}
662	
663	func terminalIcon(ok bool) string {
664		if ok {
665			return "✓"
666		}
667		return "✗"
668	}
669	
670	// reportMirrorResults renders the results table, a copy-pasteable git-clone
671	// block for the ready mirrors, and per-failure detail. It returns a
672	// SilentError (so the table isn't reprinted) when any mirror failed, giving the
673	// command a non-zero exit while still showing what succeeded.
674	func reportMirrorResults(outW, errW io.Writer, results []mirrorResult) error {
675		if len(results) == 0 {
676			return nil
677		}
678		// Headroom between the live progress block and the summary table.
679		fmt.Fprintln(outW)
680		if err := printTable(outW, mirrorCreateResultColumns, results, mirrorCreateResultRow); err != nil {
681			return err
682		}
683	
684		var readyURLs []string
685		var failures int
686		for _, r := range results {
687			if r.status == mirrorStatusReady && r.cloneURL != "" {
688				readyURLs = append(readyURLs, r.cloneURL)
689			}
690			if r.err != nil {
691				failures++
692			}
693		}
694		if len(readyURLs) > 0 {
695			fmt.Fprintln(outW, "\nClone them:")
696			for _, u := range readyURLs {
697				fmt.Fprintf(outW, "  git clone %s\n", u)
698			}
699		}
700		if failures > 0 {
701			for _, r := range results {
702				if r.err != nil {
703					fmt.Fprintf(errW, "%s/%s @ %s: %v\n", r.owner, r.repo, r.regionLabel, r.err)
704				}
705			}
706			return NewSilentError(fmt.Errorf("%d mirror(s) failed", failures))
707		}
708		return nil
709	}
710

