				return fmt.Errorf("no mirror found for gh/%s/%s; run 'entire repo mirror create github.com/%s/%s' to onboard it", owner, repo, owner, repo)
			}

			chosen, err := selectCloneTarget(cmd, mirrors, cluster)
			if err != nil {
				return err
			}

